Ext.define('BNK.view.Budget.bgx.com.BgxItmCpnt53MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxItmCpnt53MViewController',

    config: {
        viewId: 'BgxItmCpnt53M'
    },

    setOrigData: function(mtgInfo) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        // 일시
        if (mtgInfo.mtgDt && mtgInfo.mtgHr) {
            var dt = mtgInfo.mtgDt,
                hr = mtgInfo.mtgHr,
                date = new Date(dt.substr(0,4), Number(dt.substr(4,2))-1, dt.substr(6,2), hr.substr(0,2), hr.substr(2,2), hr.substr(4,2));
            refs.mtgDt.setValue(date);
            refs.mtgHr.setValue(date);
        }
        refs.mtgPlcCntn.setValue(mtgInfo.mtgPlcCntn);		// 장소
        refs.mtgPtcpPrsn.setValue(mtgInfo.mtgPtcpPrsn);		// 참석자
        refs.mtgTitCntn.setValue(mtgInfo.mtgTitCntn);		// 회의명
        refs.mtgCntn.setValue(mtgInfo.mtgCntn);				// 내용
    },

    /* 등록 */
    onSave: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            //     mtgInfo = vm.get('mtgInfo51'),
            form = refs.form,
            fields = form.getFields(),
            errMsg = '',
            trnsDt = vm.get('trnsDt'),		// 승인일자
            date = new Date(),
            aplDt = Ext.Date.format(date, 'Ymd'), 	// 상신일자
            mtgDt = Ext.Date.format(refs.mtgDt.getValue(), 'Ymd');	// 회의일자

            // 유효성 검증
            if(!form.validate()) {
                // date
                if (!fields.mtgDt.isValid() || !fields.mtgHr.isValid()) {
                    errMsg += '- ' + '일시를 정확히 입력해주세요.<br>';
            }

            // text
            for(var i = 0; i < fields.null.length; i++) {
                var field = fields.null[i];
                if (!field.isValid()) {
                    var tmp = field.getErrorMessage();
                    if (tmp.indexOf('This field is required') != -1) {
                        errMsg += '- ' + field.parent.down('container').down('displayfield').getHtml() + ' 을(를) 입력해주세요.<br>';
                    } else {
                        errMsg += '- ' + field.parent.down('container').items.items[0].getHtml() + ' : ' + tmp + '<br>';
                    }
                }
            }

            //         Ext.Msg.alert('알림', '필수값이 누락되었습니다.');
            Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '알림',
                message : errMsg,
                alwaysOnTop : true
            });
            return;
        } else if (!(mtgDt >= trnsDt && mtgDt <= aplDt)) {
            Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '알림',
                message : '- 회의일자를 정확히 입력해주세요.',
                alwaysOnTop : true
            });
            return;
        }
        else {
            if(refs.mtgCntn.getValue().length < refs.mtgCntn.minLength){
                Ext.Msg.show({
                    buttons :  {
                        yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                    },
                    title : '알림',
                    message : '내용을 30자 이상 적어주세요.',
                    alwaysOnTop : true
                });
                return;
            }
        }

        var mtgInfo = {};
        mtgInfo.mtgDt = Ext.Date.format(refs.mtgDt.getValue(), 'Ymd');
        mtgInfo.mtgHr = Ext.Date.format(refs.mtgHr.getValue(), 'His');
        mtgInfo.mtgPlcCntn = refs.mtgPlcCntn.getValue();	// 장소
        mtgInfo.mtgPtcpPrsn = refs.mtgPtcpPrsn.getValue();	// 참석자
        mtgInfo.mtgTitCntn = refs.mtgTitCntn.getValue();	// 회의명
        mtgInfo.mtgCntn = refs.mtgCntn.getValue();			// 내용

        // 등록 버튼을 클릭하면 창이 꺼지면서 데이터 저장
        me.getView().fireEvent('saveData', mtgInfo);
        me.getView().close();
    },

    /* 닫기 */
    onClose: function(button, e, eOpts) {
        this.getView().close();
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            config = component.config;

        if(config){
            var readOnly = config.readOnlyFlag,
                mtgInfo  = config.expItemInputData.expItemMtgInfo;

            vm.set('mtgInfo', config.expItemInputData.expItemMtgInfo);
            vm.set('readOnlyFlag', readOnly);
            vm.set('trnsDt', config.dt);

            // 회의록 일자 자동 지정 부분
            if(Ext.isEmpty(vm.get('mtgInfo.mtgHr'))) {
                var trnsHr = config.expItemInputData.trnsHr.substr(0,4);
                if( parseInt(trnsHr.substr(2,2)) <= 30 )
                trnsHr = trnsHr.substr(0,2) + ':00';
                else
                trnsHr = trnsHr.substr(0,2) + ':30';
                refs.mtgDt.setValue(new Date(DateUtils.parseDate(config.expItemInputData.trnsDt)));
                refs.mtgHr.setValue(trnsHr);
            }

            // 입력한 값이 있으면 불러오기
            /** '닫기'시에도 바인딩이 되어서 수동으로 전환. */
            if (mtgInfo) {
                me.setOrigData(mtgInfo);
            }

            if(readOnly) {
                me.getView().setAlwaysOnTop(true);
            }
        }
    }

});